// FUNCTION: BFME2 0x00481842 size=216 name=?xfer@PropagandaTowerBehavior@@MAEXPAVXfer@@@Z evidence=N:ledger
void PropagandaTowerBehavior::xfer(Xfer *xfer)
{
	xfer->Version1();
	UpdateModule::xfer(xfer);
	*xfer == m_lastScanFrame;

	UnsignedShort insideCount = 0;
	for (ObjectTracker *tracker = m_insideList; tracker != NULL; tracker = tracker->next)
		++insideCount;
	*xfer == insideCount;

	if (xfer->IsStoring())
	{
		for (ObjectTracker *tracker = m_insideList; tracker != NULL; tracker = tracker->next)
			XferObjectID(xfer, &tracker->objectID);
	}
	else
	{
		if (m_insideList != NULL)
			throw XferException(5, 0);

		for (UnsignedShort i = 0; i < insideCount; ++i)
		{
			ObjectTracker *tracker = new ObjectTracker;
			tracker->next = m_insideList;
			m_insideList = tracker;
			XferObjectID(xfer, &tracker->objectID);
		}
	}
}

