// FUNCTION: BFME2 0x00481A54 size=26 name=?bfmeGoBMD@BfmeThingBMD@@QAEXXZ evidence=N:ledger
void PropagandaTowerBehavior::onObjectCreated()
{
	const PropagandaTowerBehaviorModuleData *modData = (const PropagandaTowerBehaviorModuleData *)m_moduleData;

	// convert the module data's upgrade name to its template
	m_upgradeRequired = TheUpgradeCenter->findUpgrade(modData->m_upgradeRequired);
}

// FUNCTION: BFME2 0x00481A6E size=48 name=?rva00481A6E@Rva00481A6E@@UAEXHPAX@Z evidence=?:placeholder
void PropagandaTowerBehavior::onCapture(Player *oldOwner, Player *newOwner)
{
	// the tower does not work for the neutral player
	if (newOwner == ThePlayerList->getNeutralPlayer())
	{
		removeAllInfluence();
		setWakeFrame(getObject(), UPDATE_SLEEP_FOREVER);
	}
	else
		setWakeFrame(getObject(), UPDATE_SLEEP_NONE);
}

// FUNCTION: BFME2 0x00481A9E size=225 name=?rva00481A9E@Rva0048180C@@QAEXPAVObject@@_NPAURva00481A9EInfo@@@Z evidence=?:placeholder
void PropagandaTowerBehavior::effectLogic(Object *obj, Bool giving, const PropagandaTowerBehaviorModuleData *modData)
{
	if (getObject() == NULL)
		return;
	Player *player = getObject()->getControllingPlayer();
	if (player == NULL)
		return;
	Bool effectUpgraded;
	if (m_upgradeRequired != NULL)
		effectUpgraded = player->rva002AB87D(m_upgradeRequired);
	else
		effectUpgraded = false;

	if (giving)
	{
		// weapon bonus conditions 0 (ENTHUSIASTIC) and 7 (SUBLIMINAL) live at bits 8 and 15 of the object's word at +0x380
		if (obj->hasAnyDamageWeapon() == true)
		{
			if (!obj->testWeaponBonusCondition(8))
				obj->setWeaponBonusCondition(8);
			if (effectUpgraded)
			{
				if (!obj->testWeaponBonusCondition(15))
					obj->setWeaponBonusCondition(15);
			}
		}

		// grant health as well, once per second's worth of the percentage
		BodyModuleInterface *body = obj->getBodyModule();
		if (body == NULL)
			return;
		Real healthPercent;
		if (effectUpgraded)
			healthPercent = modData->m_upgradedHealPercentEachSecond;
		else
			healthPercent = modData->m_healPercentEachSecond;
		Real amount = body->getMaxHealth() * (healthPercent / (Real)BfmeLogicFramesPerSecond);
		obj->attemptHealingFromSoleBenefactor(amount, getObject(), modData->m_delayBetweenUpdates);
	}
	else
	{
		// taking the effect away
		obj->clearWeaponBonusCondition(8);
		obj->clearWeaponBonusCondition(15);
	}
}

// FUNCTION: BFME2 0x00481BAB size=7 name=?invertWord@@YAXPAI@Z evidence=N:ledger
void invertWord(unsigned int *value)
{
	*value = ~*value;
}

// FUNCTION: BFME2 0x00481C0C size=320 name=?update@PropagandaTowerBehavior@@UAE?AW4UpdateSleepTime@@XZ evidence=N:ledger
// FUNCTION: BFME2 0x00481D4C size=88 name=?removeAllInfluence@PropagandaTowerBehavior@@MAEXXZ evidence=N:ledger
void PropagandaTowerBehavior::removeAllInfluence()
{
	// take the effect off everything the tower has given it to
	for (ObjectTracker *tracker = m_insideList; tracker != NULL; tracker = tracker->next)
	{
		Object *obj = TheGameLogic->findObjectByID(tracker->objectID);
		if (obj != NULL)
			effectLogic(obj, false, (const PropagandaTowerBehaviorModuleData *)m_moduleData);
	}

	// then drop the list
	while (m_insideList != NULL)
	{
		ObjectTracker *next = m_insideList->next;
		::delete m_insideList;
		m_insideList = next;
	}
}

// FUNCTION: BFME2 0x00481DA4 size=478 name=?doScan@PropagandaTowerBehavior@@MAEXXZ evidence=N:ledger
void PropagandaTowerBehavior::doScan()
{
	const PropagandaTowerBehaviorModuleData *modData = (const PropagandaTowerBehaviorModuleData *)m_moduleData;
	Object *us = getObject();
	ObjectTracker *newInsideList = NULL;

	// the scan is when the pulse effect plays; the upgraded one once the upgrade is present
	Bool upgradePresent = FALSE;
	if (m_upgradeRequired)
	{
		switch (m_upgradeRequired->getUpgradeType())
		{
		case UPGRADE_TYPE_PLAYER:
		{
			Player *player = us->getControllingPlayer();
			upgradePresent = player->rva002AB87D(m_upgradeRequired);
			break;
		}
		case UPGRADE_TYPE_OBJECT:
			upgradePresent = us->hasUpgrade(m_upgradeRequired);
			break;
		}
	}
	if (upgradePresent == TRUE)
		FXList::doFXObj(modData->m_upgradedPulseFX, us, NULL);
	else
		FXList::doFXObj(modData->m_pulseFX, us, NULL);

	// allies that are alive, on our map status and not structures, in range
	ObjectIterator iter = ThePartitionManager->iterateObjectsInRange(us->getPosition(), modData->m_radius, 0,
		PartitionFilterRelationship(us, 4, false).link(PartitionFilterAlive().link(PartitionFilterSameMapStatus(us).link(
			&PartitionFilterAcceptByKindOf(KINDOFMASK_NONE, KindOfMaskType(KindOfMaskType::kInit, KINDOF_STRUCTURE))))), 0);
	for (Object *obj = iter.next(); obj != NULL; obj = iter.next())
	{
		if (obj == us)
			continue;

		ObjectTracker *newEntry = new ObjectTracker;
		newEntry->objectID = obj->getID();
		newEntry->next = newInsideList;
		newInsideList = newEntry;
	}

	// anything that was inside before and is not now loses the effect
	for (ObjectTracker *curr = m_insideList; curr != NULL; curr = curr->next)
	{
		ObjectTracker *found;
		for (found = newInsideList; found != NULL; found = found->next)
		{
			if (found->objectID == curr->objectID)
				break;
		}
		if (found == NULL)
		{
			Object *obj = TheGameLogic->findObjectByID(curr->objectID);
			if (obj != NULL)
				effectLogic(obj, false, modData);
		}
	}

	// replace the old list by the new one
	while (m_insideList != NULL)
	{
		ObjectTracker *next = m_insideList->next;
		::delete m_insideList;
		m_insideList = next;
	}
	m_insideList = newInsideList;
}
